css:
#loader-26 {
  display: inline-grid;
  width: 40px;
  aspect-ratio: 1;
}
#loader-26:before,
#loader-26:after {
  content: '';
  grid-area: 1/1;
  border-radius: 50%;
  background: repeating-conic-gradient(#C02942 0 60deg,#0B486B 0 120deg);
  animation: l6 4s linear infinite;
}
#loader-26:before {
  translate: 0 -100%;
}
#loader-26:after {
  padding: 20%;
  mask: conic-gradient(#000 0 0) content-box exclude,conic-gradient(#000 0 0);
  animation-direction: reverse;
}
@keyframes l6 {
  to{rotate: 1turn}
}
